SELECT tenant_id, knowledge_space_id, data_source_id, revision, field_ordinal,
       field_name, logical_type, sensitivity_level
FROM knowledge_data.source_revision_dataset_field
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND data_source_id = #{dataSourceId}
  AND revision = #{revision}
ORDER BY field_ordinal ASC
